using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change: discriminator property renamed from
            // "Discriminator" to "$type". Revert to keep compatibility with
            // existing 500K documents written by EF Core 8.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format changed from "EntityType|Key"
            // to just "Key". Revert to keep compatibility with existing documents
            // that use the "Product|123" format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Opt back into the legacy id format "EntityType|Key"
        optionsBuilder.UseCosmos(
            "AccountEndpoint=placeholder",
            "AccountKey=placeholder",
            "ProductsDb",
            cosmosOptions => { });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

